{
  "name": "AMI双轴超导磁体系统（带持久电流开关）",
  "name_en": "AMI Two-Axis Superconducting Magnet System with Persistent Current Switches",
  "manufacturer": "American Magnetics, Inc.",
  "description": "这是一套双轴超导磁体系统，包含强轴Z和弱轴Y，并配有持久电流开关。系统可在两个正交方向上建立和保持磁场，并通过调节磁场大小、分量和角度，为低温物理、纳米器件和量子器件实验提供稳定可控的磁环境。",
  "description_en": "This is a two-axis superconducting magnet system with a strong Z axis, a weaker Y axis, and persistent current switches. It is used to generate and maintain magnetic fields along two orthogonal directions, allowing control of total field, field components, and field angle for low-temperature physics, nanodevice, and quantum-device experiments.",
  "tag_hints": [
    "superconducting magnet",
    "vector magnetic field",
    "persistent current switch",
    "cryogenic experiments",
    "magnet power supply control",
    "field-angle control",
    "low-temperature physics"
  ],
  "actions": [
    {
      "action_name": "auto-get_all",
      "description": "获取磁体系统的整体状态信息。",
      "description_en": "Get the overall status of the magnet system."
    },
    {
      "action_name": "auto-get_source_current_z",
      "description": "获取Z轴电源输出电流。",
      "description_en": "Get the source current on the Z axis."
    },
    {
      "action_name": "auto-get_source_current_y",
      "description": "获取Y轴电源输出电流。",
      "description_en": "Get the source current on the Y axis."
    },
    {
      "action_name": "auto-set_source_current_z",
      "description": "设置Z轴电源输出电流。",
      "description_en": "Set the source current on the Z axis."
    },
    {
      "action_name": "auto-set_source_current_y",
      "description": "设置Y轴电源输出电流。",
      "description_en": "Set the source current on the Y axis."
    },
    {
      "action_name": "auto-get_heater_current_z",
      "description": "获取Z轴持久电流开关加热器电流。",
      "description_en": "Get the persistent-switch heater current on the Z axis."
    },
    {
      "action_name": "auto-get_heater_current_y",
      "description": "获取Y轴持久电流开关加热器电流。",
      "description_en": "Get the persistent-switch heater current on the Y axis."
    },
    {
      "action_name": "auto-get_switch_state_z",
      "description": "获取Z轴持久电流开关状态。",
      "description_en": "Get the persistent-switch state on the Z axis."
    },
    {
      "action_name": "auto-get_switch_state_y",
      "description": "获取Y轴持久电流开关状态。",
      "description_en": "Get the persistent-switch state on the Y axis."
    },
    {
      "action_name": "auto-set_switch_state_z",
      "description": "设置Z轴持久电流开关状态。",
      "description_en": "Set the persistent-switch state on the Z axis."
    },
    {
      "action_name": "auto-set_switch_state_y",
      "description": "设置Y轴持久电流开关状态。",
      "description_en": "Set the persistent-switch state on the Y axis."
    },
    {
      "action_name": "auto-set_field",
      "description": "设置磁场总幅值。",
      "description_en": "Set the total magnetic field magnitude."
    },
    {
      "action_name": "auto-get_field",
      "description": "获取磁场总幅值。",
      "description_en": "Get the total magnetic field magnitude."
    },
    {
      "action_name": "auto-set_angle",
      "description": "设置磁场方向角。",
      "description_en": "Set the magnetic field angle."
    },
    {
      "action_name": "auto-get_angle",
      "description": "获取磁场方向角。",
      "description_en": "Get the magnetic field angle."
    },
    {
      "action_name": "auto-set_field_z",
      "description": "设置Z轴磁场分量。",
      "description_en": "Set the Z-axis magnetic field component."
    },
    {
      "action_name": "auto-set_field_y",
      "description": "设置Y轴磁场分量。",
      "description_en": "Set the Y-axis magnetic field component."
    },
    {
      "action_name": "auto-get_field_z",
      "description": "获取Z轴磁场分量。",
      "description_en": "Get the Z-axis magnetic field component."
    },
    {
      "action_name": "auto-get_field_y",
      "description": "获取Y轴磁场分量。",
      "description_en": "Get the Y-axis magnetic field component."
    },
    {
      "action_name": "auto-step_z_magfield_to_value",
      "description": "将Z轴磁场逐步调节到目标值。",
      "description_en": "Step the Z-axis magnetic field to a target value."
    },
    {
      "action_name": "auto-step_y_magfield_to_value",
      "description": "将Y轴磁场逐步调节到目标值。",
      "description_en": "Step the Y-axis magnetic field to a target value."
    },
    {
      "action_name": "auto-disconnect_z_source",
      "description": "断开Z轴电源与磁体回路。",
      "description_en": "Disconnect the source from the Z-axis magnet circuit."
    },
    {
      "action_name": "auto-disconnect_y_source",
      "description": "断开Y轴电源与磁体回路。",
      "description_en": "Disconnect the source from the Y-axis magnet circuit."
    },
    {
      "action_name": "auto-bring_z_source_to_field",
      "description": "使Z轴电源电流与当前磁体场值对应。",
      "description_en": "Bring the Z-axis source current to the value corresponding to the present magnet field."
    },
    {
      "action_name": "auto-bring_y_source_to_field",
      "description": "使Y轴电源电流与当前磁体场值对应。",
      "description_en": "Bring the Y-axis source current to the value corresponding to the present magnet field."
    },
    {
      "action_name": "auto-measure_field_z",
      "description": "测量或读取Z轴磁场。",
      "description_en": "Measure or read the magnetic field on the Z axis."
    },
    {
      "action_name": "auto-measure_field_y",
      "description": "测量或读取Y轴磁场。",
      "description_en": "Measure or read the magnetic field on the Y axis."
    },
    {
      "action_name": "auto-BtoI_z",
      "description": "将Z轴目标磁场换算为所需电流。",
      "description_en": "Convert a target Z-axis magnetic field to the required current."
    },
    {
      "action_name": "auto-BtoI_y",
      "description": "将Y轴目标磁场换算为所需电流。",
      "description_en": "Convert a target Y-axis magnetic field to the required current."
    },
    {
      "action_name": "auto-ItoB_z",
      "description": "将Z轴电流换算为对应磁场。",
      "description_en": "Convert Z-axis current to the corresponding magnetic field."
    },
    {
      "action_name": "auto-ItoB_y",
      "description": "将Y轴电流换算为对应磁场。",
      "description_en": "Convert Y-axis current to the corresponding magnetic field."
    },
    {
      "action_name": "auto-fake_folder",
      "description": "记录一次磁体状态变化事件标记。",
      "description_en": "Record a marker for a magnet state-change event."
    }
  ]
}

